def save_day_store(path: str | Path | None, store: dict[str, Any]) -> None:
    if not path:
        return
    p = Path(path)
    try:
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(json.dumps(store, indent=2))
    except Exception:  # noqa: BLE001
        pass
